let quickEntry=null,quickEntryPending=false,quickEntryGeneration=0,quickLoginBusy=false,quickLoginController=null,quickRestorePending=false,authMutationBusy=false,authRevision=0;
let catalogMode='topics',catalogScope='school',sheet=0,polling=false,sending=false,connected=true,outbox=[],rejected=[],retryTimer=null,toastTimer=null,authInvite=null,authLoginHint='',authReady=false;
