 $('pen').onclick=()=>setPen('pen');$('eraser').onclick=()=>setPen('eraser');$('pen-color').oninput=e=>{workspace.draw.color=e.target.value;};$('pen-width').oninput=e=>{workspace.draw.width=Number(e.target.value);};$('undo-stroke').onclick=()=>{const last=[...effective(activeAttempt).strokes].reverse().find(s=>s.author===account.id||s.actor?.id===account.id);if(last)action(workspace.id,'undo',{strokeId:last.id});else toast('Ваших штрихов пока нет.');};
 $('trainer-control')?.addEventListener('click',async()=>{if(queuedFor(a.id).length){toast('Дождитесь сохранения текущих действий.');return;}const id=workspace.id;$('trainer-control').disabled=true;try{const latest=await api('/attempts/'+encodeURIComponent(id));if(!workspace||workspace.id!==id)return;remember(latest);await action(id,'control',{controller:latest.controller==='teacher'?'student':'teacher'});}catch(error){notice(errorText(error),true);}finally{updateWorkspace();}});
